export const PRICES={maps:{free:5000,rates:[7,5.6,4.2,2.1,.53]},street:{free:5000,rates:[14,11.2,8.4,4.2,1.05]}};
export function estimate(count,sku){let total=0,start=PRICES[sku].free;const bounds=[100000,500000,1000000,5000000,Infinity];for(let i=0;i<bounds.length;i++){const n=Math.max(0,Math.min(count,bounds[i])-start);total+=n*PRICES[sku].rates[i]/1000;start=bounds[i];}return total;}
export function deadzone(value){return Math.abs(value)<.14?0:Math.sign(value)*(Math.abs(value)-.14)/.86;}
export function createFlight(lat=25.033,lng=121.5654){return {lat,lng,h:0,heading:0,vx:0,vy:0,speed:0,maxSpeedKmh:30,time:0,mode:'grounded',paused:false};}
export function step(s,input,delta){const dt=Math.min(.1,Math.max(0,delta));if(s.paused||s.mode==='grounded'){s.speed=0;return s;}s.time+=dt;const radians=s.heading*Math.PI/180; s.heading=(s.heading+input.yaw*65*dt+360)%360;let f=input.forward*s.maxSpeedKmh/3.6,r=input.strafe*s.maxSpeedKmh/3.6;if(s.mode==='takingOff'||s.mode==='landing'){f=r=0;}const targetX=Math.sin(radians)*f+Math.cos(radians)*r,targetY=Math.cos(radians)*f-Math.sin(radians)*r;const a=1-Math.exp(-5*dt);s.vx+=(targetX-s.vx)*a;s.vy+=(targetY-s.vy)*a;s.lat=Math.max(-85,Math.min(85,s.lat+s.vy*dt/111320));s.lng=((s.lng+s.vx*dt/(111320*Math.cos(s.lat*Math.PI/180))+540)%360)-180;s.speed=Math.hypot(s.vx,s.vy);if(s.mode==='takingOff'){s.h=Math.min(15,s.h+5*dt);if(s.h===15)s.mode='flying';}else if(s.mode==='landing'){s.h=Math.max(0,s.h-5*dt);if(s.h===0){s.mode='grounded';s.vx=s.vy=s.speed=0;}}else{s.h=Math.max(1,Math.min(500,s.h+input.lift*8*dt));}return s;}
